import { writeFileSync } from "node:fs";
import { resolveAndroidApiBase } from "./android-env.js";

try {
  const apiBase = resolveAndroidApiBase();
  const content = [
    "// Generated by scripts/prepare-android-config.js before an Android build.",
    `export const ANDROID_API_BASE_URL = ${JSON.stringify(apiBase)};`,
    "",
  ].join("\n");
  writeFileSync("src/generated/androidConfig.js", content);
  console.log(apiBase ? `Android API target: ${apiBase}` : "Android uses official sources directly.");
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
